const raw = $input.first().json;
const body = raw.body ?? raw;

const assets = Array.isArray(body.assets) ? body.assets : [];
const imageUrl = assets[0]?.url ?? null;
const creds = body.credentials && typeof body.credentials === 'object' ? body.credentials : {};

return [
  {
    json: {
      event: body.event,
      tenantId: body.tenantId,
      productId: body.productId,
      productName: body.productName,
      contentId: body.contentId,
      platform: (body.platform ?? '').toLowerCase(),
      title: body.title,
      copy: body.copy,
      scheduledDate: body.scheduledDate,
      visualFormat: body.visualFormat,
      versionId: body.versionId,
      assets,
      imageUrl,
      callbackUrl: body.callbackUrl,
      credentials: creds,
      metaIgUserId: creds.pageId || $env.META_IG_USER_ID || '',
      linkedinAuthorUrn: creds.accountId
        ? (String(creds.accountId).startsWith('urn:') ? creds.accountId : `urn:li:organization:${creds.accountId}`)
        : ($env.LINKEDIN_AUTHOR_URN || ''),
    },
  },
];

const item = $input.first().json;
const igUserId = item.metaIgUserId;
const accessToken = $env.META_ACCESS_TOKEN;
const imageUrl = item.imageUrl;
const caption = item.copy;

if (!igUserId) throw new Error('Falta META_IG_USER_ID o credentials.pageId');
if (!accessToken) throw new Error('Falta META_ACCESS_TOKEN en variables de entorno n8n');
if (!imageUrl) throw new Error('El payload no trae assets[0].url (URL firmada)');

const container = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://graph.facebook.com/v21.0/${igUserId}/media`,
  qs: {
    image_url: imageUrl,
    caption,
    access_token: accessToken,
  },
});

const published = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://graph.facebook.com/v21.0/${igUserId}/media_publish`,
  qs: {
    creation_id: container.id,
    access_token: accessToken,
  },
});

return [
  {
    json: {
      ...item,
      publishPlatform: 'instagram',
      externalPostId: String(published.id ?? container.id),
      providerResponse: published,
    },
  },
];

const item = $input.first().json;
const pageId = item.credentials?.pageId || item.metaIgUserId;
const accessToken = $env.META_ACCESS_TOKEN;
const imageUrl = item.imageUrl;
const caption = item.copy;

if (!pageId) throw new Error('Falta pageId en credentials o META_IG_USER_ID');
if (!accessToken) throw new Error('Falta META_ACCESS_TOKEN');
if (!imageUrl) throw new Error('Sin imageUrl en assets');

const published = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://graph.facebook.com/v21.0/${pageId}/photos`,
  qs: {
    url: imageUrl,
    caption,
    access_token: accessToken,
  },
});

return [
  {
    json: {
      ...item,
      publishPlatform: 'facebook',
      externalPostId: String(published.id ?? published.post_id ?? ''),
      providerResponse: published,
    },
  },
];

const item = $input.first().json;
const accessToken = $env.LINKEDIN_ACCESS_TOKEN;
const author = item.linkedinAuthorUrn;
const text = item.copy;

if (!accessToken) throw new Error('Falta LINKEDIN_ACCESS_TOKEN');
if (!author) throw new Error('Falta LINKEDIN_AUTHOR_URN o credentials.accountId');

// Post de texto + enlace al asset (evita flujo multi-paso de upload de imagen en el ejemplo).
const commentary = item.imageUrl ? `${text}\n\n${item.imageUrl}` : text;

const body = {
  author,
  lifecycleState: 'PUBLISHED',
  specificContent: {
    'com.linkedin.ugc.ShareContent': {
      shareCommentary: { text: commentary },
      shareMediaCategory: 'NONE',
    },
  },
  visibility: {
    'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC',
  },
};

const published = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.linkedin.com/v2/ugcPosts',
  headers: {
    Authorization: `Bearer ${accessToken}`,
    'X-Restli-Protocol-Version': '2.0.0',
    'Content-Type': 'application/json',
  },
  body,
  json: true,
});

return [
  {
    json: {
      ...item,
      publishPlatform: 'linkedin',
      externalPostId: String(published.id ?? ''),
      providerResponse: published,
    },
  },
];

const item = $input.first().json;
return [
  {
    json: {
      ...item,
      publishPlatform: item.platform,
      externalPostId: null,
      publishSkipped: true,
      skipReason: `Plataforma no soportada: ${item.platform}`,
    },
  },
];
